/**
 * Text resources `pnpm brand:gen` writes next to the native pictures
 * (scripts/brand/native-assets.ts): the iOS splash image set with its dark
 * variant, the Android adaptive icon and the splash colours (Android 12+
 * draws its own splash from them; values-night is the dark theme).
 */
import {
	ANDROID_RES,
	IOS_ASSETS,
	type NativeBrand,
	hasMonochromeLayer,
} from "./native-assets.js";

export interface TextAsset {
	readonly path: string;
	readonly text: string;
}

const XML_HEAD = '<?xml version="1.0" encoding="utf-8"?>';
const GENERATED_NOTE =
	"<!-- Generated by pnpm brand:gen (scripts/brand/native-assets.ts) from brand.config.json. Do not edit. -->";

/** The adaptive icon, with its monochrome (themed) layer when it has one. */
function adaptiveIcon(monochrome: boolean): string {
	const themed = monochrome
		? '\n    <monochrome android:drawable="@mipmap/ic_launcher_monochrome"/>'
		: "";
	return `${XML_HEAD}
${GENERATED_NOTE}
<adaptive-icon xmlns:android="http://schemas.android.com/apk/res/android">
    <background android:drawable="@mipmap/ic_launcher_background"/>
    <foreground android:drawable="@mipmap/ic_launcher_foreground"/>${themed}
</adaptive-icon>
`;
}

function colours(entries: Record<string, string>): string {
	const items = Object.entries(entries)
		.map(
			([name, value]) =>
				`    <color name="${name}">${value.toUpperCase()}</color>`,
		)
		.join("\n");
	return `${XML_HEAD}
${GENERATED_NOTE}
<resources>
${items}
</resources>
`;
}

/** Xcode asset catalog JSON, in the two-space layout Xcode itself writes. */
function xcodeJson(value: unknown): string {
	return `${JSON.stringify(value, null, 2).replace(/":/g, '" :')}\n`;
}

const IOS_SPLASH_SET = {
	images: [
		{ filename: "splash-2732x2732.png", idiom: "universal" },
		{
			appearances: [{ appearance: "luminosity", value: "dark" }],
			filename: "splash-2732x2732-dark.png",
			idiom: "universal",
		},
	],
	info: { author: "xcode", version: 1 },
};

const IOS_ICON_SET = {
	images: [
		{
			filename: "AppIcon-512@2x.png",
			idiom: "universal",
			platform: "ios",
			size: "1024x1024",
		},
	],
	info: { author: "xcode", version: 1 },
};

export function nativeTextFiles(brand: NativeBrand): TextAsset[] {
	const adaptive = adaptiveIcon(hasMonochromeLayer(brand));
	return [
		{
			path: `${IOS_ASSETS}Splash.imageset/Contents.json`,
			text: xcodeJson(IOS_SPLASH_SET),
		},
		{
			path: `${IOS_ASSETS}AppIcon.appiconset/Contents.json`,
			text: xcodeJson(IOS_ICON_SET),
		},
		{
			path: `${ANDROID_RES}mipmap-anydpi-v26/ic_launcher.xml`,
			text: adaptive,
		},
		{
			path: `${ANDROID_RES}mipmap-anydpi-v26/ic_launcher_round.xml`,
			text: adaptive,
		},
		{
			path: `${ANDROID_RES}values/brand_colors.xml`,
			text: colours({
				splash_background: brand.colors.background,
				splash_icon_background: brand.colors.primary,
			}),
		},
		{
			path: `${ANDROID_RES}values-night/brand_colors.xml`,
			text: colours({
				splash_background: brand.colors.backgroundDark,
				splash_icon_background: brand.colors.primary,
			}),
		},
	];
}
